import {OwnerListingsComponent} from '../owner-listings.component';
import {FormsModule} from '@angular/forms';
import {mediaObjectUrl,MEDIA_ROUTES} from '../services/media-routes';
import {SiteTextPipe} from '../home/site-text.pipe';
import {Component,OnInit,OnDestroy} from '@angular/core';import {CommonModule} from '@angular/common';import {ActivatedRoute,RouterModule} from '@angular/router';import {HttpClient} from '@angular/common/http';import {Subscription,firstValueFrom,timeout} from 'rxjs';
import {PlatformLayoutComponent} from '../layout/platform-layout/platform-layout.component';import {ReservationAuthService} from '../services/reservation-auth.service';import {AssetAccessService} from '../services/asset-access.service';import {LanguageService} from '../services/language.service';import {PLATFORM_ASSET_TEXT} from './platform-asset.text';
@Component({selector:'app-platform-asset',standalone:true,imports:[OwnerListingsComponent,CommonModule,FormsModule,RouterModule,PlatformLayoutComponent,SiteTextPipe],templateUrl:'./platform-asset.component.html',styleUrls:['./platform-asset.component.scss']})
export class PlatformAssetComponent implements OnInit,OnDestroy{
 panel:'summary'|'preview'|'edit'='summary';
 imageErrors=new Set<string>();
 priceUnitKey(){return ({hour:'ui.labels.t5073129fadb8',day:'ui.labels.t240ce85d68f5',night:'ui.labels.t3359902f0d42'} as Record<string,string>)[this.data?.asset?.pricing?.pricingUnit]||'';}
 priceUnitFallback(){const unit=this.data?.asset?.pricing?.pricingUnit;return ({hour:this.x('heure','hour'),day:this.x('jour','day'),night:this.x('nuit','night')} as Record<string,string>)[unit]||unit||'';}
 review(){this.panel='summary';setTimeout(()=>{if(typeof document!=='undefined')document.getElementById('listing-review')?.scrollIntoView({block:'start',behavior:'smooth'});});}
 get editScope(){const a=this.data?.asset;return a?{type:a.assetType,id:a.id}:null;}
 async onListingSaved(){this.panel='summary';await this.refresh();this.message=this.x('Annonce enregistrée. Vous pouvez la valider.','Listing saved. You can now approve it.');}
form:any={};photos:string[]=[];files:File[]=[];working=false;reason='';publish=false;message='';data:any=null;loading=false;error='';uid='';private initialAction=true;private sequence=0;private subscription?:Subscription;
 constructor(private http:HttpClient,private auth:ReservationAuthService,public access:AssetAccessService,public language:LanguageService,private route:ActivatedRoute){}
 t(key:string){return PLATFORM_ASSET_TEXT[this.language.currentLanguage]?.[key]||PLATFORM_ASSET_TEXT.en[key]||key;}
 ngOnInit(){this.subscription=this.route.paramMap.subscribe(()=>{void this.refresh();});}
 ngOnDestroy(){this.sequence++;this.subscription?.unsubscribe();this.data=null;}
 link(tail='home'){const a=this.data?.asset;return a?['/',a.assetType,a.id,...tail.split('/')]:['/platform/admin'];}
 x(fr:string,en:string){return this.language.currentLanguage==='fr'?fr:en;}
 propertyType(value:any){return typeof value==='number'?'number':typeof value==='boolean'?'checkbox':'text';}
 image(path:string){return mediaObjectUrl(path);}
 open(panel:'summary'|'preview'|'edit'){if(this.working)return;this.panel=panel;this.error='';if(panel==='edit'){this.form=JSON.parse(JSON.stringify(this.data.asset));this.photos=this.assetPhotos();this.files=[];}}
 assetPhotos(){const m=this.data?.asset?.media||{};return [...new Set<string>([m.hero,m.cover,...(Array.isArray(m.gallery)?m.gallery:[])].filter((x:any)=>typeof x==='string'&&x))];}
 choose(event:Event){const input=event.target as HTMLInputElement;this.files=Array.from(input.files||[]);}
 private endpoint(){const a=this.data.asset;return '/api/manage/assets/'+[a.assetType,a.id].map(encodeURIComponent).join('/')+'/content';}
 async save(){if(this.working||!this.form.name?.trim()||!Number.isFinite(Number(this.form.pricing?.basePrice))||Number(this.form.pricing.basePrice)<0)return;const a=this.data.asset,seq=this.sequence,endpoint=this.endpoint(),revision=this.data.moderation.revision;this.working=true;this.error='';try{const headers=await this.auth.headers();while(this.files.length){const file=this.files[0];const form=new FormData();form.append('file',file,file.name);form.append('category',a.assetType==='boat'?'boat':'gallery');form.append('subject',a.id);form.append('resourceType',a.assetType);form.append('resourceId',a.id);const uploaded=await firstValueFrom(this.http.post<any>(MEDIA_ROUTES.upload,form,{headers}));if(!uploaded?.path)throw Error('upload_failed');this.photos.push(uploaded.path);this.files.shift();}this.files=[];if(seq!==this.sequence||(await this.auth.user()).uid!==this.uid)throw Error('asset_context_changed');const asset:any={name:this.form.name.trim(),headline:this.form.headline||'',description:this.form.description||'','pricing/basePrice':Number(this.form.pricing.basePrice),'location/city':this.form.location?.city||'','location/area':this.form.location?.area||'','location/country':this.form.location?.country||'','media/hero':this.photos[0]||null,'media/cover':this.photos[0]||null,'media/gallery':this.photos,'media/configured':true};for(const [key,value]of Object.entries(this.form.properties||{}))asset['properties/'+key]=value;await firstValueFrom(this.http.patch(endpoint,{asset,expectedRevision:revision},{headers}));if(seq!==this.sequence)return;this.panel='summary';await this.refresh();this.message=this.x('Annonce enregistrée. Relisez-la avant de la valider.','Listing saved. Review it before approval.');}catch(e:any){this.error=this.x('Enregistrement impossible.','Could not save.')+' '+String(e?.error?.error||'');}finally{this.working=false;}}
 async decide(decision:'approved'|'rejected'){if(this.working||(decision==='rejected'&&!this.reason.trim()))return;this.working=true;this.error='';const a=this.data.asset,seq=this.sequence;try{await firstValueFrom(this.http.post('/api/platform/admin/listings/'+[a.assetType,a.id].map(encodeURIComponent).join('/')+'/moderation',{decision,revision:this.data.moderation.revision,reason:this.reason,reviewDraft:true,publish:decision==='approved'&&this.publish},{headers:await this.auth.headers()}));if(seq!==this.sequence)return;await this.refresh();this.message=this.x('Décision enregistrée.','Decision saved.');}catch(e:any){this.error=this.x('Décision impossible. Actualisez le dossier.','Could not save decision. Refresh the file.')+' '+String(e?.error?.error||'');}finally{this.working=false;}}
 async refresh(){const sequence=++this.sequence;this.loading=true;this.data=null;this.error='';try{const type=String(this.route.snapshot.paramMap.get('type')||''),id=String(this.route.snapshot.paramMap.get('id')||'');if(!['boat','car','property','parking','pool'].includes(type)||!/^[a-zA-Z0-9_-]+$/.test(id))throw Error('invalid_scope');const uid=(await this.auth.user()).uid;this.uid=uid;const data=await firstValueFrom(this.http.get<any>('/api/platform/admin/assets/'+[type,id].map(encodeURIComponent).join('/'),{headers:await this.auth.headers()}).pipe(timeout(20000)));if(sequence!==this.sequence||(await this.auth.user()).uid!==uid)return;this.data=data;this.imageErrors.clear();if(this.initialAction&&this.route.snapshot.queryParamMap?.get('action')==='edit')this.panel='edit';this.initialAction=false;this.publish=false;this.reason='';}catch(e:any){if(sequence===this.sequence)this.error=this.t(e.status===403?'forbidden':e.status===404?'notFound':'error');}finally{if(sequence===this.sequence)this.loading=false;}}
}
